/* Generated by tools/table_build.py from examples/meter/profile.json; do not edit by hand.
 * The changes of the running firmware that the pack 'meter' asks the loader to make at the start. One entry is five words: the kind
 * (0x10 and: 0 a data word, 1 a call in L1 code, 2 a call in DDR code, 3 a jump in L1 code, 4 a jump in DDR code,
 * 5 the load of an address in DDR code; in its high half the bytes its trampoline copies), the place, the function
 * of ours, the CRC-32 of the firmware's bytes the change replaces or its trampoline copies, and the room for the
 * trampoline or 0. No byte of the firmware stands in this table.
 */
.section .rodata
.balign 4
.global op1f_boot_table
.type op1f_boot_table, STT_OBJECT
op1f_boot_table:
    .long 0x00080014, 0x8f00ef54, meter_beat_entry, 0x88644db8, meter_beat_room    /* Ours runs the firmware's beat function once through a trampoline of eight bytes, with the caller's registers and stack, then gives the caller 1 on the first beat of a bar of the pack's meter, 2 on any other beat, and -1 as the function answered it. */
    .long 0x00080012, 0x8fc83362, meter_tape_a, 0xce2a76f1, meter_tape_a_room    /* Ours asks its own function how many lines make a bar of the pack's meter at the tape's grid setting. For the firmware's own (4/4, 8/8) it puts every register back as it came and jumps to its room, where the firmware's call runs unchanged; else it returns that count behind the place in place of the routine's answer. */
    .long 0x00080012, 0x8fc8338e, meter_tape_b, 0x6c7cee2a, meter_tape_b_room    /* Ours asks its own function for the dividend of the line spacing, puts every register back as it came, R0 with that dividend when there is one, and jumps to its room, where the firmware's own call of the divide runs and returns behind the place. */
    .long 0x00080012, 0x8fc9f19a, meter_tape_c, 0x6c7cee2a, meter_tape_c_room    /* Ours asks its own function for the dividend of the snap unit (one grid line of the pack's meter), puts every register back as it came, R0 with that dividend when there is one, and jumps to its room, where the firmware's own call of the divide runs and returns behind the place. */
    .long 0x00080012, 0x8c0c2ca2, meter_tape_d, 0x6c7cee2a, meter_tape_d_room    /* Ours asks its own function for the dividend of the bar (a bar of the pack's meter), puts every register back as it came, R0 with that dividend when there is one, and jumps to its room, where the firmware's own call of the divide runs and returns behind the place. */
    .long 0x00080014, 0x8f01fd00, meter_countin_entry, 0x278dbbd2, meter_countin_room    /* Ours runs the firmware's step function once through a trampoline of eight bytes, with the caller's registers and stack, then has its own function set the count-in's length while none runs and keep the pack's own copy of the record, and returns to the caller with every register as the function left it. */
    .long 0x00000015, 0x8f00f180, meter_countin_record, 0xbe0a46fc, 0    /* The address becomes that of the pack's own record of the count-in, which ours keeps every block behind the firmware's step function: at four quarter-note clicks a copy of the firmware's, else the same with the pack's own clicks and the accent on the last of them. */
    .long 0x00080014, 0x8fc5fc64, meter_popup_load, 0xbd8aa0bf, meter_popup_load_room    /* Ours has its own function set the number about to be loaded, when a count-in of the pack's length runs, so that the popup counts 1 to the number of clicks; then it puts every register back as it came and jumps to its room, where the firmware's own load runs and goes on behind the place. */
.size op1f_boot_table, .-op1f_boot_table
.global op1f_boot_table_end
.type op1f_boot_table_end, STT_OBJECT
op1f_boot_table_end:
